/**
 * Icons on slides — find one by meaning, draw it the same way everywhere.
 *
 * ## Why a vendored set, and why paths
 *
 * Infographics without icons read as coloured boxes; a model asked for "an
 * icon" invents names that exist nowhere. So the deck has one closed set — a
 * curated Lucide subset (`vendor/lucide/icons.ts`, ISC, regenerated by
 * `scripts/vendor-deck-icons.mjs`) — and every icon is a normalised stroke
 * path in a 24×24 box. The HTML renderer draws it as an SVG path; the
 * PowerPoint writer draws it as a native freeform (`a:custGeom`) whose line
 * colour is a theme slot, so in PowerPoint an icon is a shape the person can
 * recolour, resize and edit points of, not a picture.
 *
 * ## Why search has synonyms
 *
 * Lucide's own tags describe the drawing ("bag", "baggage"); slides talk
 * about the business ("revenue", "onboarding", "compliance"). {@link findIcons}
 * scores names and tags, then a small table of business words maps the rest,
 * so "Make this slide visual" can give each item a fitting icon and an
 * unknown icon name in the agent's input is answered with the nearest real
 * ones rather than silently dropped.
 *
 * @module shared/ui/canvas/deck-icons
 */

import { LUCIDE_ICONS } from './vendor/lucide/icons';

export const ICON_NAMES: readonly string[] = Object.keys(LUCIDE_ICONS);

export function isDeckIcon(name: unknown): name is string {
  return typeof name === 'string' && Object.prototype.hasOwnProperty.call(LUCIDE_ICONS, name);
}

/** The path data (SVG `d`) of an icon in its 24×24 box. */
export function iconPath(name: string): string | undefined {
  return isDeckIcon(name) ? LUCIDE_ICONS[name]![1] : undefined;
}

export type IconCmd = ['M' | 'L', number, number] | ['C', number, number, number, number, number, number] | ['Z'];

const parsed = new Map<string, IconCmd[]>();

/** The icon as absolute commands (what PowerPoint's freeform needs). */
export function iconCommands(name: string): IconCmd[] {
  const hit = parsed.get(name);
  if (hit) return hit;
  const d = iconPath(name) ?? '';
  const out: IconCmd[] = [];
  for (const m of d.matchAll(/([MLCZ])([^MLCZ]*)/g)) {
    const v = m[2]!.trim() ? m[2]!.trim().split(/\s+/).map(Number) : [];
    if (m[1] === 'Z') out.push(['Z']);
    else if (m[1] === 'C') out.push(['C', v[0]!, v[1]!, v[2]!, v[3]!, v[4]!, v[5]!]);
    else out.push([m[1] as 'M' | 'L', v[0]!, v[1]!]);
  }
  parsed.set(name, out);
  return out;
}

