export interface IconHit { name: string; score: number }

function words(s: string): string[] {
  return s.toLowerCase().replace(/[^a-z0-9\s-]/g, ' ').split(/[\s-]+/).filter(w => w.length > 1);
}

/** Icons for a query, best first. */
export function findIcons(query: string, limit = 12): IconHit[] {
  const q = words(query);
  if (!q.length) return [];
  const scores = new Map<string, number>();
  const add = (name: string, s: number): void => { if (isDeckIcon(name)) scores.set(name, (scores.get(name) ?? 0) + s); };
  const joined = q.join('-');
  if (isDeckIcon(joined)) add(joined, 20);
  for (const w of q) {
    const stem = w.replace(/(ies|es|s)$/, (m) => (m === 'ies' ? 'y' : ''));
    for (const [i, name] of (SYNONYMS[w] ?? SYNONYMS[stem] ?? []).entries()) add(name, 9 - i);
    for (const name of ICON_NAMES) {
      const parts = name.split('-');
      if (name === w || name === stem) add(name, 12);
      else if (parts.includes(w) || parts.includes(stem)) add(name, 5 / parts.length + 2);
      const tags = LUCIDE_ICONS[name]![0].split(/\s+/);
      if (tags.includes(w) || tags.includes(stem)) add(name, 3);
      else if (w.length >= 4 && tags.some(t => t.startsWith(w))) add(name, 1);
    }
  }
  return [...scores.entries()].map(([name, score]) => ({ name, score: Math.round(score * 10) / 10 }))
    .sort((a, b) => b.score - a.score || a.name.localeCompare(b.name)).slice(0, limit);
}

/** The best icon for some text, when one fits well enough to say the same thing. */
export function iconFor(text: string, taken: Set<string> = new Set()): string | undefined {
  const hits = findIcons(text, 8).filter(h => h.score >= 5);
  return (hits.find(h => !taken.has(h.name)) ?? hits[0])?.name;
}

/** An icon name from loose input ("Rocket", "rocket icon", "lucide:rocket"), or undefined. */
export function toIconName(v: unknown): string | undefined {
  if (typeof v !== 'string') return undefined;
  const k = v.trim().toLowerCase().replace(/^lucide[:/-]/, '').replace(/\s+icon$/, '').replace(/[\s_]+/g, '-');
  if (isDeckIcon(k)) return k;
  return findIcons(k, 1).find(h => h.score >= 8)?.name;
}
